namespace Gordic.Ada.WebClient {

    /** DAO pro Věcný profil Ada části */
    export class GVecnyProfilAdaDAO implements Gordic.Eko.WebClient.IGVecnyProfilDAO {
        constructor(public opts: { rok: number, ico: string, cislo: string }) {
            //debugger;
            this.opts = this.opts ?? {};
        }
        list(parentContent: GContent<IGContentBase, any>, dto: any, opts: { rok: number, ico: string, cislo: string } | undefined): JQuery.Promise<any[], any, any> {
            //debugger;
            return parentContent.isl.AkceVecnyProfil.list({
                filters: { rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }
            }).getData();
        }
        evidovat(parentContent: GContent<IGContentBase, any>, dto: any, opts?: {} | undefined): JQueryPromise<any> {
            if (dto.cis_plan == 0)
            {
                return parentContent.isl.AkceVecnyProfil.create({ data: dto, rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).getData();
            }
            else
            {
                return parentContent.isl.AkceVecnyProfil.update({ data: dto, rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).getData();
            }
        }
        schvalit(parentContent: GContent<IGContentBase, any>, dto: any, opts?: {} | undefined): JQueryPromise<any> {
            return parentContent.isl.AkceVecnyProfil.schvalit({ data: dto, rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).getData();
        }
        stornovat(parentContent: GContent<IGContentBase, any>, dto: any, opts?: {} | undefined): JQueryPromise<any> {
            return parentContent.isl.AkceVecnyProfil.delete({ data: dto, rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).getData();
        }
        zrusitStorno(parentContent: GContent<IGContentBase, any>, dto: any, opts?: {} | undefined): JQueryPromise<any> {
            return parentContent.isl.AkceVecnyProfil.undelete({ data: dto, rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).getData();
        }

        hromadnaKontrolaOpravneni(parentContent: GContent, dto: any[], operace: Gordic.Eko.Interface.GVecnyProfilOperace, opts?: {}): JQueryPromise<Isl.GServiceGroupResponse<any>> {
            throw new Error("Method not implemented.")
            // return parentContent.isl.AkceVecnyProfil.checkMassPermissionsBeforeOperation({ data: dto[0], rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).get();
        }
        hromadnaOperace(parentContent: GContent, dto: any[], operace: Gordic.Eko.Interface.GVecnyProfilOperace, opts?: {}): JQueryPromise<Isl.GServiceGroupResponse<any>> {
            throw new Error("Method not implemented.")
            // return parentContent.isl.AkceVecnyProfil.massOperation({ data: dto[0], rok: this.opts.rok, ico: this.opts.ico, cislo: this.opts.cislo }).get();
        }

        vytvoritNovouPolozku(parentContent: GContent<IGContentBase, any>, opts?: {} | undefined): JQueryPromise<any> {
            return parentContent.isl.AkceVecnyProfil.createNewDefaultItem({ in_cislo: this.opts.cislo }).getData();
        }
       
        destroy(): void {

        }
    }
}